package com.agrolink.controller;import com.agrolink.dto.product.*;import com.agrolink.service.ProductService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController{private final ProductService s;public ProductController(ProductService s){this.s=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ProductResponse create(Authentication a,@Valid @RequestBody ProductRequest r){return s.create(a.getName(),r);}@GetMapping public List<ProductResponse> search(@RequestParam(required=false)String q,@RequestParam(required=false)Long categoryId){return s.search(q,categoryId);}@GetMapping("/{id}") public ProductResponse get(@PathVariable Long id){return s.get(id);}@GetMapping("/mine") public List<ProductResponse> mine(Authentication a){return s.mine(a.getName());}@PutMapping("/{id}") public ProductResponse update(Authentication a,@PathVariable Long id,@Valid @RequestBody ProductRequest r){return s.update(a.getName(),id,r);}@DeleteMapping("/{id}") public void delete(Authentication a,@PathVariable Long id){s.delete(a.getName(),id);}}
